    const consumption=$('#consumptionForm');if(consumption){consumption.addEventListener('input',e=>{if(e.target.name==='credit_consumption_due')e.target.dataset.suggested='false';});consumption.addEventListener('change',event=>{if(event.target.name==='credit_customer_id'){updateCustomerTitle();suggestDueDate();}});const box=document.createElement('div');box.className='op-credit-consumption';box.innerHTML=select('credit_customer_id','Cliente a crédito (opcional)','Elegir un cliente no crea deuda. Confirma únicamente con el botón Agregar a cartera del cliente.',[['','Consumo normal · elegir cliente solo si irá a crédito']])+input('credit_consumption_due','Fecha acordada de pago','Se necesita únicamente al agregar a cartera.','date')+'<p>Al confirmar, los consumos de esta cuenta pasan a la cartera del cliente y liberan la mesa o persona. Si pagará ahora, confirma la selección y cobra normalmente.</p><button class="primary" type="button" id="addConsumptionToCredit">Agregar a cartera del cliente</button>';box.hidden=!allowed('customers.read')||!allowed('sales.write');box.querySelector('[name=credit_customer_id]').required=false;(consumption.querySelector('.consumption-editor')||consumption).prepend(box);const feedback=document.createElement('div');feedback.id='creditConsumptionFeedback';feedback.className='op-credit-feedback';feedback.setAttribute('role','alert');feedback.hidden=true;feedback.innerHTML='<p></p><button type="button" class="ghost" data-credit-edit-customer hidden>Editar cliente y cupo</button>';box.append(feedback);feedback.querySelector('button').onclick=()=>customerEditor(model().customers.find(c=>c.id===box.querySelector('[name=credit_customer_id]').value));}
